def transform(grid):
    h, w = len(grid), len(grid[0])
    # Recolor the solid frame/divider lines (the non-background color) as in demo.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    line_color = next(v for v in set(v for row in grid for v in row) if v != bg)
    rows = [r for r in range(h) if all(v == line_color for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == line_color for r in range(h))]
    out = [row[:] for row in grid]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out

